// legacyPlaceholderPoster is THE legacy placeholder value (poster-backfill):
// docs enriched before the write-side missing-art drop still store it as
// sources.shikimori.poster, and the settle only SKIPPED it at acquire time —
// the repair leg must strip the key from the stored document itself.
const legacyPlaceholderPoster = "https://shikimori.io/assets/globals/missing_original.jpg"

// placeholderDoc builds a stored document carrying the legacy placeholder in
// sources.shikimori.poster beside a sibling namespace field (id), a doc-level
// field (title), and a REAL poster URL in a second namespace — the repair
// must remove exactly the one placeholder key and preserve everything else.
// The tmdb URL targets a guaranteed-refused loopback port: the settle half
// attempts (and logs) the acquire, and the pass continues.
func placeholderDoc() json.RawMessage {
	return json.RawMessage(`{"title":"Fringe","sources":{"shikimori":{"id":12345,"poster":"https://shikimori.io/assets/globals/missing_original.jpg"},"tmdb":{"poster":"http://127.0.0.1:1/tmdb/real.jpg"}}}`)
}

// reloadedRow is the post-Settle state one repair assertion set reads back:
// the stored document plus the timestamps the write-back gate shows through
// (updated_at advances on every store write, and on nothing else).
type reloadedRow struct {
	doc       json.RawMessage
	createdAt time.Time
	updatedAt time.Time
}

// TestSettleRepairStripsLegacyPlaceholderPoster is THE /fix repro (task 1.1 —
// red on base a467358, where Settle only skips placeholders at acquire time
// and never writes a document back): stored series AND item documents
// carrying a legacy placeholder sources.<ns>.poster come out of Settle
// REPAIRED — the placeholder key removed, every other field and the row
// identity preserved, the write-back visible as an updated_at advance — and
// the acquire + GC reference sets derive from the REPAIRED docs: the
// placeholder never re-triggers acquisition, and a seeded placeholder fetch
// row plus its blob dir are reclaimed as reference-lost.
func TestSettleRepairStripsLegacyPlaceholderPoster(t *testing.T) {
	ctx := context.Background()
	svc, st, root := newTestService(t)
	libID, err := st.CreateLibrary(ctx, "artmod", "/media/lib", "Library")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}

	// A pre-existing fetch row + blob dir for the placeholder URL: after the
	// repair it is referenced by NO document, so GC reclaims both. (On base
	// the un-repaired doc still references it and both survive.)
	seedSHA := strings.Repeat("ab", 32)
	seedHash := urlHash(legacyPlaceholderPoster, KindPoster)
	if err := st.InsertArtFetch(ctx, seedHash, seedSHA, KindPoster); err != nil {
		t.Fatalf("seed placeholder fetch row: %v", err)
	}
	seedDir := filepath.Join(root, seedSHA)
	if err := os.MkdirAll(seedDir, 0o755); err != nil {
		t.Fatalf("seed blob dir: %v", err)
	}
	if err := os.WriteFile(filepath.Join(seedDir, "original.jpeg"), []byte("seed"), 0o644); err != nil {
		t.Fatalf("seed blob bytes: %v", err)
	}

	if err := st.PutSeries(ctx, store.Series{
		ModuleID:      "artmod",
		LibraryID:     libID,
		RelativePath:  "Fringe (2008)",
		Document:      placeholderDoc(),
		SchemaVersion: 1,
		Status:        "ready",
		CreatedAt:     time.Now().UTC().Add(-time.Hour),
	}); err != nil {
		t.Fatalf("PutSeries: %v", err)
	}
	if err := st.PutItem(ctx, store.Item{
		ID:            "itm_repair",
		ModuleID:      "artmod",
		LibraryID:     libID,
		FileID:        "file-repair",
		RelativePath:  "Fight Club (1999)/Fight Club (1999).mkv",
		MediaType:     "movie",
		Document:      placeholderDoc(),
		SchemaVersion: 1,
		Status:        "ready",
		CreatedAt:     time.Now().UTC().Add(-time.Hour),
	}); err != nil {
		t.Fatalf("PutItem: %v", err)
	}

	// Pre-Settle state of both rows (identity timestamps + the stored doc).
	var preSeries, preItem reloadedRow
	sr, err := st.GetSeriesByPath(ctx, libID, "Fringe (2008)")
	if err != nil {
		t.Fatalf("load stored series: %v", err)
	}
	preSeries = reloadedRow{sr.Document, sr.CreatedAt, sr.UpdatedAt}
	it, err := st.GetItem(ctx, "itm_repair")
	if err != nil {
		t.Fatalf("load stored item: %v", err)
	}
	preItem = reloadedRow{it.Document, it.CreatedAt, it.UpdatedAt}

	if err := svc.Settle(ctx); err != nil {
		t.Fatalf("Settle: %v", err)
	}

	rows := []struct {
		name   string
		reload func() (reloadedRow, error)
		pre    reloadedRow
	}{
		{"series", func() (reloadedRow, error) {
			sr, err := st.GetSeriesByPath(ctx, libID, "Fringe (2008)")
			return reloadedRow{sr.Document, sr.CreatedAt, sr.UpdatedAt}, err
		}, preSeries},
		{"item", func() (reloadedRow, error) {
			it, err := st.GetItem(ctx, "itm_repair")
			return reloadedRow{it.Document, it.CreatedAt, it.UpdatedAt}, err
		}, preItem},
	}
	for _, row := range rows {
		t.Run(row.name, func(t *testing.T) {
			got, err := row.reload()
			if err != nil {
				t.Fatalf("reload: %v", err)
			}
			var doc map[string]any
			if err := json.Unmarshal(got.doc, &doc); err != nil {
				t.Fatalf("repaired document does not parse: %v\n%s", err, got.doc)
			}
			sources, _ := doc["sources"].(map[string]any)
			if sources == nil {
				t.Fatalf("sources namespace map lost:\n%s", got.doc)
			}
			shikimori, _ := sources["shikimori"].(map[string]any)
			if shikimori == nil {
				t.Fatalf("sources.shikimori object lost:\n%s", got.doc)
			}
			if _, ok := shikimori["poster"]; ok {
				t.Fatalf("legacy placeholder key survived the repair:\n%s", got.doc)
			}
			if id, ok := shikimori["id"].(float64); !ok || id != 12345 {
				t.Fatalf("sibling namespace field lost by the repair:\n%s", got.doc)
			}
			tmdb, _ := sources["tmdb"].(map[string]any)
			if tmdb == nil || tmdb["poster"] != "http://127.0.0.1:1/tmdb/real.jpg" {
				t.Fatalf("real-URL namespace lost by the repair:\n%s", got.doc)
			}
			if doc["title"] != "Fringe" {
				t.Fatalf("doc-level field lost by the repair:\n%s", got.doc)
			}
			if !got.createdAt.Equal(row.pre.createdAt) {
				t.Fatalf("created_at advanced %v -> %v, want preserved", row.pre.createdAt, got.createdAt)
			}
			if !got.updatedAt.After(row.pre.updatedAt) {
				t.Fatalf("updated_at did not advance (%v -> %v): no write-back happened", row.pre.updatedAt, got.updatedAt)
			}
		})
	}

	// The reference sets derive from the REPAIRED docs: the placeholder is
	// neither re-acquired nor a surviving GC reference.
	if sha, err := st.LookupArtFetch(ctx, seedHash); !errors.Is(err, sql.ErrNoRows) {
		t.Fatalf("placeholder fetch row survived (sha %q, err %v): the reference set must derive from the repaired docs", sha, err)
	}
	if _, err := os.Stat(seedDir); !os.IsNotExist(err) {
		t.Fatalf("seeded blob dir still on disk (%v), want reclaimed", err)
	}
	hashes, _, _, err := st.ListArtFetches(ctx)
	if err != nil {
		t.Fatalf("ListArtFetches: %v", err)
	}
	if len(hashes) != 0 {
		t.Fatalf("art_fetches = %v, want empty (a stripped placeholder is never re-acquired)", hashes)
	}
}

// TestSettleRepairKeepsRealURLsByteIdentical pins the exact path-prefix rule
// from the keep side: a real URL whose path merely CONTAINS similar
// substrings — a lookalike path segment, the placeholder name under a
// different path prefix, the placeholder echoed in a query string — is NEVER
// stripped and its row is NEVER rewritten, and a corrupt document is left
// untouched (the tolerant floor). Genuinely-fetchable URLs double as proof
// the settle half still acquires real URLs: the negative is about the
// write-back gate, not about stopping the walk.
func TestSettleRepairKeepsRealURLsByteIdentical(t *testing.T) {
	ctx := context.Background()
	svc, st, _ := newTestService(t)
	libID, err := st.CreateLibrary(ctx, "artmod", "/media/lib", "Library")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}

	poster := jpegBytes(t, 40, 60)
	liveSrv, hits := newUpstream(t, serveBytes(http.StatusOK, poster, 0))
	closedSrv := httptest.NewServer(http.NotFoundHandler())
	closedSrv.Close() // guaranteed-refused loopback for kept-but-unfetchable lookalikes

	cases := []struct {
		name        string
		path        string
		posterURL   string
		wantFetched bool // a real URL by the rule: the settle half must acquire it
	}{
		{"real_fetchable_url", "Real One", liveSrv.URL + "/real_poster.jpg", true},
		{"lookalike_path_substring", "Lookalike A", closedSrv.URL + "/missing/art.jpg", false},
		{"placeholder_name_other_prefix", "Lookalike B", closedSrv.URL + "/v2/assets/globals/missing_original.jpg", false},
		{"placeholder_in_query_string", "Query Bearer", liveSrv.URL + "/poster.jpg?fallback=/assets/globals/missing_original.jpg", true},
	}

	docs := make([]json.RawMessage, len(cases))
	pre := make([]reloadedRow, len(cases))
	for i, tc := range cases {
		// The URLs are interpolation-safe by construction: no quotes, no
		// backslashes, nothing JSON-escapable.
		docs[i] = json.RawMessage(`{"title":"Real","sources":{"tmdb":{"poster":"` + tc.posterURL + `"}}}`)
		if err := st.PutSeries(ctx, store.Series{
			ModuleID:      "artmod",
			LibraryID:     libID,
			RelativePath:  tc.path,
			Document:      docs[i],
			SchemaVersion: 1,
			Status:        "ready",
			CreatedAt:     time.Now().UTC().Add(-time.Hour),
		}); err != nil {
			t.Fatalf("PutSeries %s: %v", tc.name, err)
		}
		sr, err := st.GetSeriesByPath(ctx, libID, tc.path)
		if err != nil {
			t.Fatalf("load stored %s: %v", tc.name, err)
		}
		pre[i] = reloadedRow{sr.Document, sr.CreatedAt, sr.UpdatedAt}
	}

	// A corrupt document rides the same pass. A malformed document can only
	// exist in the series table (items' generated columns make the store
	// itself reject malformed JSON at the boundary): the tolerant floor keeps
	// it byte-identical, and rewriting a misshapen doc is never the repair's
	// business.
	corruptDoc := json.RawMessage(`{"sources":{"shikimori":{"poster":"https://shikimori.io/assets/globals/missing_original.jpg"`)
	if err := st.PutSeries(ctx, store.Series{
		ModuleID:      "artmod",
		LibraryID:     libID,
		RelativePath:  "corrupt/doc",
		Document:      corruptDoc,
		SchemaVersion: 1,
		Status:        "ready",
		CreatedAt:     time.Now().UTC().Add(-time.Hour),
	}); err != nil {
		t.Fatalf("PutSeries corrupt: %v", err)
	}
	srPre, err := st.GetSeriesByPath(ctx, libID, "corrupt/doc")
	if err != nil {
		t.Fatalf("load stored corrupt series: %v", err)
	}
	preCorrupt := reloadedRow{srPre.Document, srPre.CreatedAt, srPre.UpdatedAt}

	if err := svc.Settle(ctx); err != nil {
		t.Fatalf("Settle: %v", err)
	}

	for i, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			sr, err := st.GetSeriesByPath(ctx, libID, tc.path)
			if err != nil {
				t.Fatalf("reload: %v", err)
			}
			if !bytes.Equal(sr.Document, docs[i]) {
				t.Fatalf("document rewritten:\nhave %s\nwant %s", sr.Document, docs[i])
			}
			if !sr.UpdatedAt.Equal(pre[i].updatedAt) {
				t.Fatalf("updated_at advanced %v -> %v: row rewritten without a placeholder removal", pre[i].updatedAt, sr.UpdatedAt)
			}
			_, err = st.LookupArtFetch(ctx, urlHash(tc.posterURL, KindPoster))
			if tc.wantFetched && err != nil {
				t.Fatalf("real URL not acquired by the settle half: %v", err)
			}
			if !tc.wantFetched && !errors.Is(err, sql.ErrNoRows) {
				t.Fatalf("lookalike unexpectedly has a fetch row: %v", err)
			}
		})
	}

	srGot, err := st.GetSeriesByPath(ctx, libID, "corrupt/doc")
	if err != nil {
		t.Fatalf("reload corrupt series: %v", err)
	}
	if !bytes.Equal(srGot.Document, corruptDoc) {
		t.Fatalf("corrupt document rewritten:\nhave %s\nwant %s", srGot.Document, corruptDoc)
	}
	if !srGot.UpdatedAt.Equal(preCorrupt.updatedAt) {
		t.Fatalf("corrupt series updated_at advanced %v -> %v: corrupt docs must be left untouched", preCorrupt.updatedAt, srGot.UpdatedAt)
	}

	if got := hits.Load(); got != 2 {
		t.Fatalf("upstream hits = %d, want 2 (the two real URLs, once each)", got)
	}
}

// TestPosterRepairGolden drives the repair strip from the committed golden
// fixture internal/art/testdata/golden/poster_repair.json (poster-backfill
// 1.2, the internal/api/testdata/golden/ idiom): every vector's expected
// document IS stripMissingPosters' spec — placeholder key stripped with every
// other field surviving, a real-URL document returned byte for byte
// (changed=false), a mixed-source document half-repaired, and the
// relative-form placeholder (rows enriched before the absolute-URL helper)
// stripped by the path-prefix rule alone. The comparison is SEMANTIC JSON
// equality — the strip re-marshals through maps, so key order is not
// identity — and the changed=false contract additionally pins raw byte
// identity, because the caller writes back only on an actual removal.
func TestPosterRepairGolden(t *testing.T) {
	raw, err := os.ReadFile(filepath.Join("testdata", "golden", "poster_repair.json"))
	if err != nil {
		t.Fatalf("read golden fixture: %v", err)
	}
	var fixture struct {
		Vectors []struct {
			Name     string          `json:"name"`
			Input    json.RawMessage `json:"input"`
			Expected json.RawMessage `json:"expected"`
			Changed  bool            `json:"changed"`
		} `json:"vectors"`
	}
	if err := json.Unmarshal(raw, &fixture); err != nil {
		t.Fatalf("decode golden fixture: %v", err)
	}
	if len(fixture.Vectors) < 3 {
		t.Fatalf("golden fixture carries %d vectors, want >= 3", len(fixture.Vectors))
	}
	for _, v := range fixture.Vectors {
		t.Run(v.Name, func(t *testing.T) {
			got, changed := stripMissingPosters(v.Input)
			if changed != v.Changed {
				t.Fatalf("changed = %v, want %v\ngot: %s", changed, v.Changed, got)
			}
			if !v.Changed && !bytes.Equal(got, v.Input) {
				t.Fatalf("unchanged vector must return raw byte for byte:\nhave %s\nwant %s", got, v.Input)
			}
			var gotAny, wantAny any
			if err := json.Unmarshal(got, &gotAny); err != nil {
				t.Fatalf("repaired document does not parse: %v\n%s", err, got)
			}
			if err := json.Unmarshal(v.Expected, &wantAny); err != nil {
				t.Fatalf("expected document does not parse: %v\n%s", err, v.Expected)
			}
			if !reflect.DeepEqual(gotAny, wantAny) {
				t.Fatalf("semantic mismatch:\nhave %s\nwant %s", got, v.Expected)
			}
		})
	}
}
